<form method="post" enctype="multipart/form-data" action="<?=e(url($editing?'admin/products/'.$p['id'].'/edit':'admin/products/add'))?>"><?=csrf_field()?><div class="row g-4"><div class="col-xl-8"><section class="admin-card form-section"><h2>Product information</h2><div class="row g-3"><div class="col-md-8"><label>Product name *</label><input class="form-control" name="name" required maxlength="190" value="<?=e($p['name']??'')?>"></div><div class="col-md-4"><label>Product code</label><input class="form-control" name="product_code" maxlength="80" value="<?=e($p['product_code']??'')?>"></div><div class="col-md-6"><label>Category *</label><select class="form-select" name="category_id" required><option value="">Select category</option><?php foreach($categories as $category):?><option value="<?=$category['id']?>" <?=($p['category_id']??'')==$category['id']?'selected':''?>><?=e($category['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Slug</label><input class="form-control" name="slug" value="<?=e($p['slug']??'')?>" placeholder="Generated from product name"></div><div class="col-12"><label>Short description</label><textarea class="form-control" name="short_description" rows="3" maxlength="600"><?=e($p['short_description']??'')?></textarea></div><div class="col-12"><label>Full description</label><textarea class="form-control" name="full_description" rows="6"><?=e($p['full_description']??'')?></textarea></div></div></section><section class="admin-card form-section mt-4"><h2>Application and performance content</h2><div class="row g-3"><div class="col-md-6"><label>Features</label><textarea class="form-control" name="features" rows="5"><?=e($p['features']??'')?></textarea></div><div class="col-md-6"><label>Benefits</label><textarea class="form-control" name="benefits" rows="5"><?=e($p['benefits']??'')?></textarea></div><div class="col-md-6"><label>Applications</label><textarea class="form-control" name="applications" rows="5"><?=e($p['applications']??'')?></textarea></div><div class="col-md-6"><label>Technical information</label><textarea class="form-control" name="technical_information" rows="5"><?=e($p['technical_information']??'')?></textarea></div><div class="col-12"><label>Packaging information</label><textarea class="form-control" name="packaging_information" rows="3"><?=e($p['packaging_information']??'')?></textarea></div><div class="col-12"><label>Official product website URL</label><input class="form-control" type="url" name="official_url" value="<?=e($p['official_url']??'')?>" placeholder="https:// — leave empty unless verified"><small class="field-help">Only add the genuine manufacturer or official product page. No URL is generated automatically.</small></div></div></section></div><div class="col-xl-4"><section class="admin-card form-section sticky-form"><h2>Publish</h2><label>Status</label><select class="form-select" name="status"><option value="DRAFT" <?=($p['status']??'')==='DRAFT'?'selected':''?>>Disabled / Draft</option><option value="PUBLISHED" <?=($p['status']??'')==='PUBLISHED'?'selected':''?>>Enabled / Published</option></select><label class="check-row"><input type="checkbox" name="featured" value="1" <?=!empty($p['featured'])?'checked':''?>> Featured product</label><label>Product image</label><?php if(!empty($p['main_image'])):?><img class="image-preview" src="<?=e(url($p['main_image']))?>" alt="Current product image"><?php endif;?><input class="form-control" type="file" name="main_image" accept="image/jpeg,image/png,image/webp"><small class="field-help">JPG, PNG or WEBP. Maximum 5 MB.</small><div class="form-buttons"><button class="btn btn-primary" type="submit">Save Product</button><a class="btn btn-light" href="<?=e(url('admin/products'))?>">Cancel</a></div></section></div></div></form>

